// Game page: runs inside <iframe sandbox="allow-scripts"> with an opaque origin. Receives
// snapshots from the host via postMessage, predicts the own player with the shared sim,
// interpolates everyone else and renders with @tcg/kit + the game's assets.ts. Spectating (no own
// player): the camera follows the action instead (director.ts). V switches playing/spectating.
// One page per game: apps/client/games/<slug>.ts (generated by scripts/registry.mjs) calls
// startGame with that game's rules and assets.
import "./game.css";
import { FixedStep, SnapshotBuffer, createFx, damp, lerp, lerpBodies, type GameAssets } from "@tcg/kit";
import { Predictor, type Entity, type GameRules, type SnapMessage } from "@tcg/shared";
import { parseHostMessage, type GameMessage } from "../bridge.js";
import { InputSender, readKeys } from "./input.js";
import { Director } from "./director.js";

const TICK_MS = 1000 / 15;
// Predicted position further than this from the server's: snap instead of smoothing.
const SNAP_DIST = 120;

export function startGame(rules: GameRules, assets: GameAssets<Entity>): void {
  const canvas = document.getElementById("c") as HTMLCanvasElement;
  const ctx = canvas.getContext("2d")!;
  const fx = createFx();
  const scene = assets.scene ?? { width: 800, height: 600 };
  fx.camera.bounds = { x: 0, y: 0, w: scene.width, h: scene.height };
  fx.camera.zoom = scene.zoom ?? 1;

  const buf = new SnapshotBuffer<Record<string, Entity>>({ hz: 15, delay: 2 });
  const step = new FixedStep(TICK_MS);
  const sender = new InputSender();
  const keys = new Set<string>();
  let predictor: Predictor | null = null;
  let me: string | null = null;
  let statusText = "connecting…";
  let draining = false;
  let names: Record<string, string> = {};
  let lastSnap: SnapMessage | null = null;
  let acked = 0;
  // Own player: previous/current predicted tick state, plus a decaying visual correction.
  let prevMe: Entity | null = null;
  let curMe: Entity | null = null;
  let offX = 0, offY = 0;
  let spectator = false;
  const director = new Director({}, { x: scene.width / 2, y: scene.height / 2 });
  let directed = false; // camera placed by the director at least once

  // Exposed for the headless check and debugging (the frame is cross-origin to the host anyway).
  const stats = { frames: 0, snaps: 0, predicted: false, pending: 0, corrections: 0, me: null as { x: number; y: number } | null, spectator: false, focus: null as string | null };
  (globalThis as { __tcg?: unknown }).__tcg = stats;

  function toHost(m: GameMessage): void {
    if (parent !== window) parent.postMessage(m, "*");
  }

  addEventListener("message", (e) => {
    if (e.source !== parent || parent === window) return;
    const m = parseHostMessage(e.data);
    if (!m) return;
    if (m.t === "status") {
      statusText = m.text;
      draining = m.draining;
      spectator = stats.spectator = m.spectator === true;
      if (m.me && m.me !== me) { me = m.me; fx.me = me; predictor = new Predictor(rules, me); prevMe = curMe = null; }
    } else if (m.t === "key") {
      if (m.down) { keys.add(m.key); toggle(m.key); } else keys.delete(m.key);
    } else onSnap(m.snap);
  });

  for (const type of ["keydown", "keyup"] as const) {
    addEventListener(type, (e) => {
      const k = e.key.toLowerCase();
      if (type === "keydown") { keys.add(k); fx.sfx.unlock(); if (!e.repeat) toggle(k); } else keys.delete(k);
      if (k.startsWith("arrow") || k === " ") e.preventDefault();
    });
  }
  addEventListener("pointerdown", () => fx.sfx.unlock());
  addEventListener("blur", () => keys.clear());

  // V: play <-> spectate. The host reconnects with or without ?spectate=1.
  function toggle(k: string): void {
    if (k === "v") toHost({ t: "mode", spectate: !spectator });
  }

  function own(): Entity | null {
    const e = me && predictor?.world?.entities[me];
    return e ? { ...e } : null;
  }

  function onSnap(snap: SnapMessage): void {
    if (!snap.entities || typeof snap.tick !== "number") return;
    stats.snaps++;
    draining = draining || snap.draining === true;
    names = snap.names ?? {};
    buf.push(snap.tick, snap.entities, performance.now());
    assets.onSnapshot?.(lastSnap?.entities ?? null, snap.entities, fx);
    if (spectator) director.observe(snap.entities, names, lastSnap ? Math.min(1, Math.max(0, snap.tick - lastSnap.tick) * TICK_MS / 1000) : 0);
    lastSnap = snap;
    if (!me || !predictor) return;
    acked = snap.acks?.[me]?.[0] ?? acked;
    const before = curMe;
    stats.predicted = !draining && predictor.reconcile(snap);
    stats.pending = predictor.pending.length;
    curMe = own();
    if (!before || !curMe) { prevMe = curMe; return; }
    // Hide the correction: keep drawing where we were and let the offset decay.
    const dx = before.x - curMe.x, dy = before.y - curMe.y;
    if (dx * dx + dy * dy > SNAP_DIST * SNAP_DIST) { offX = offY = 0; prevMe = curMe; return; }
    if (dx || dy) stats.corrections++;
    offX += dx; offY += dy;
    if (prevMe) prevMe = { ...prevMe, x: prevMe.x - dx, y: prevMe.y - dy };
  }

  function tick(now: number): void {
    if (spectator) return; // no player: nothing to send or predict
    const input = readKeys(keys);
    const out = sender.tick(input, now, acked);
    if (out) toHost({ t: "input", ...out });
    if (!predictor || draining) return;
    predictor.step(input, sender.seq);
    prevMe = curMe;
    curMe = own();
  }

  function resize(): number {
    const dpr = Math.min(2, devicePixelRatio || 1);
    const w = innerWidth, h = innerHeight;
    if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
    }
    fx.camera.resize(w, h);
    return dpr;
  }

  let last = performance.now();
  function frame(now: number): void {
    const ms = Math.min(250, now - last);
    last = now;
    fx.dt = ms / 1000;
    fx.time += fx.dt;
    stats.frames++;
    const steps = step.advance(ms);
    for (let i = 0; i < steps; i++) tick(now);

    const dpr = resize();
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.fillStyle = scene.background ?? "#0b0e14";
    ctx.fillRect(0, 0, fx.camera.viewW, fx.camera.viewH);

    const s = buf.sample(now);
    let list: Entity[] = s ? lerpBodies(s.a, s.b, s.t) : [];
    // Own player: predicted, blended between local ticks, minus the decaying correction.
    offX = damp(offX, 0, 10, fx.dt);
    offY = damp(offY, 0, 10, fx.dt);
    let mine: Entity | undefined;
    if (stats.predicted && curMe) {
      const a = prevMe ?? curMe, t = step.alpha;
      mine = { ...curMe, x: lerp(a.x, curMe.x, t) + offX, y: lerp(a.y, curMe.y, t) + offY, r: lerp(a.r, curMe.r, t) };
      list = list.filter((e) => e.id !== me);
      list.push(mine);
    } else mine = list.find((e) => e.id === me);
    stats.me = mine ? { x: mine.x, y: mine.y } : null;
    if (spectator) {
      const t = director.target(list);
      fx.camera.follow(t.x, t.y, !directed);
      directed = true;
      stats.focus = director.focus;
    } else if (mine) fx.camera.follow(mine.x, mine.y, stats.frames === 1);
    fx.camera.update(fx.dt);

    fx.camera.apply(ctx);
    assets.drawBackground?.(ctx, fx);
    for (const e of list) if (fx.camera.visible(e.x, e.y, e.r * 4)) assets.drawEntity(ctx, e, fx);
    fx.particles.update(fx.dt);
    fx.particles.draw(ctx);
    // Names are drawn by this frozen renderer, never by game code (spec §10).
    ctx.font = "12px system-ui, sans-serif";
    ctx.textAlign = "center";
    ctx.fillStyle = "rgba(255,255,255,0.85)";
    for (const e of list) if (names[e.id] && fx.camera.visible(e.x, e.y, 40)) ctx.fillText(names[e.id], e.x, e.y - e.r - 6);
    fx.camera.reset(ctx);

    assets.drawOverlay?.(ctx, fx);
    ctx.textAlign = "left";
    ctx.font = "13px system-ui, sans-serif";
    ctx.fillStyle = draining ? "#fca5a5" : "rgba(255,255,255,0.6)";
    ctx.fillText(statusText, 10, 20);
    if (spectator && director.focus && names[director.focus]) ctx.fillText(`watching ${names[director.focus]}`, 10, 38);
    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
  toHost({ t: "ready" });
}
